CREATE DATABASE IF NOT EXISTS kamara_wellness CHARACTER SET utf8mb4;
USE kamara_wellness;
CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(50) UNIQUE NOT NULL,password VARCHAR(255) NOT NULL,name VARCHAR(100),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS customers(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,phone VARCHAR(30),address VARCHAR(255),birth_date DATE NULL,member_level ENUM('Reguler','Silver','Gold') DEFAULT 'Reguler',points INT DEFAULT 0,notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS services(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,category VARCHAR(50),price DECIMAL(12,0) DEFAULT 0,promo_price DECIMAL(12,0) NULL,commission_percent DECIMAL(5,2) DEFAULT 0,active TINYINT DEFAULT 1);
CREATE TABLE IF NOT EXISTS therapists(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,phone VARCHAR(30),base_salary DECIMAL(12,0) DEFAULT 0,active TINYINT DEFAULT 1);
CREATE TABLE IF NOT EXISTS bookings(id INT AUTO_INCREMENT PRIMARY KEY,customer_id INT NOT NULL,therapist_id INT NULL,service_id INT NOT NULL,booking_date DATE NOT NULL,booking_time TIME NOT NULL,status ENUM('Menunggu','Dikonfirmasi','Selesai','Batal') DEFAULT 'Menunggu',notes VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(customer_id) REFERENCES customers(id),FOREIGN KEY(service_id) REFERENCES services(id));
CREATE TABLE IF NOT EXISTS transactions(id INT AUTO_INCREMENT PRIMARY KEY,customer_id INT NULL,therapist_id INT NULL,service_id INT NOT NULL,price DECIMAL(12,0) DEFAULT 0,discount DECIMAL(12,0) DEFAULT 0,total DECIMAL(12,0) DEFAULT 0,commission DECIMAL(12,0) DEFAULT 0,payment_method ENUM('Tunai','Transfer','QRIS') DEFAULT 'Tunai',trx_date DATE NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(service_id) REFERENCES services(id));
CREATE TABLE IF NOT EXISTS products(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,unit VARCHAR(20),stock INT DEFAULT 0,min_stock INT DEFAULT 5,price DECIMAL(12,0) DEFAULT 0);
CREATE TABLE IF NOT EXISTS attendance(id INT AUTO_INCREMENT PRIMARY KEY,therapist_id INT NOT NULL,att_date DATE NOT NULL,check_in TIME NULL,check_out TIME NULL,status ENUM('Hadir','Izin','Sakit','Alpha') DEFAULT 'Hadir',FOREIGN KEY(therapist_id) REFERENCES therapists(id));
CREATE TABLE IF NOT EXISTS medical_records(id INT AUTO_INCREMENT PRIMARY KEY,customer_id INT NOT NULL,visit_date DATE NOT NULL,complaint TEXT,diagnosis TEXT,treatment TEXT,blood_sugar VARCHAR(20),uric_acid VARCHAR(20),blood_pressure VARCHAR(20),FOREIGN KEY(customer_id) REFERENCES customers(id));
CREATE TABLE IF NOT EXISTS promos(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,discount_type ENUM('persen','nominal') DEFAULT 'persen',discount_value DECIMAL(12,2) DEFAULT 0,start_date DATE NULL,end_date DATE NULL,active TINYINT DEFAULT 1);
